    /// <summary>
    /// Sets default background for chats; adds the background to the list of installed backgrounds
    /// </summary>
    public Task<TdLib.TdApi.Objects.Background> SetDefaultBackgroundAsync(InputBackground background = default, BackgroundType type = default, bool forDarkTheme = default)
    {

           using var activity =  StartCallActivity("SetDefaultBackgroundAsync", typeof(SetDefaultBackground).FullName ?? "SetDefaultBackgroundAsync");

           try
           {
             return client.SetDefaultBackgroundAsync(background, type, forDarkTheme);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
